use std::evm::Address
use std::evm::units::{Duration, Wei, ether, hours, seconds}
use ingot::types::{
    MAX_RECIPIENTS,
    MAX_SELECTORS,
    MAX_TARGETS,
    MAX_TOKENS,
    Policy,
    SEL_APPROVE,
    SEL_TRANSFER,
    SEL_TRANSFER_FROM,
    TargetKind,
    TargetRule,
    TokenAmount,
    TokenRule,
}

pub const ADDR_TOKEN: Address = Address::new(0x1000000000000000000000000000000000000001)
pub const ADDR_TREASURY: Address = Address::new(0x2000000000000000000000000000000000000002)

pub fn default_policy() -> Policy {
    var targets: [TargetRule; MAX_TARGETS] = [TargetRule::empty(); MAX_TARGETS]
    // Target 0: Demo ERC-20 token (kind Erc20, sorted selectors: approve, transferFrom, transfer)
    var selectors_token: [u32; MAX_SELECTORS] = [0; MAX_SELECTORS]
    selectors_token[0] = SEL_APPROVE
    selectors_token[1] = SEL_TRANSFER_FROM
    selectors_token[2] = SEL_TRANSFER

    targets[0] = TargetRule {
        target: ADDR_TOKEN,
        kind: TargetKind::Erc20,
        allow_eth_transfer: false,
        delegate_ok: false,
        n_selectors: 3,
        selectors: selectors_token,
    }

    // Target 1: Treasury EOA (kind Generic, allow_eth_transfer = true)
    targets[1] = TargetRule {
        target: ADDR_TREASURY,
        kind: TargetKind::Generic,
        allow_eth_transfer: true,
        delegate_ok: false,
        n_selectors: 0,
        selectors: [0; MAX_SELECTORS],
    }

    var tokens: [TokenRule; MAX_TOKENS] = [TokenRule::empty(); MAX_TOKENS]
    tokens[0] = TokenRule {
        token: ADDR_TOKEN,
        max_per_tx: TokenAmount::from(100_000_000_000_000_000_000),
        // 100 tokens
        max_per_window: TokenAmount::from(500_000_000_000_000_000_000),
        // 500 tokens
        max_approve: TokenAmount::from(100_000_000_000_000_000_000),
        // 100 tokens
    }

    Policy {
        version: 1,
        n_targets: 2,
        targets,
        max_per_tx: ether(1) / 10,
        // 0.1 ETH
        max_per_window: ether(1) / 2,
        // 0.5 ETH
        window: hours(24),
        n_tokens: 1,
        tokens,
        n_recipients: 0,
        recipients: [Address::zero(); MAX_RECIPIENTS],
        max_actions_per_window: 0,
        cooldown: seconds(0),
        breaker_threshold: 0,
    }
}

pub fn policy_for_agent(_ max_tx: Wei, _ max_win: Wei) -> Policy {
    var pol = default_policy()
    if max_tx.as_wei() > 0 {
        pol.max_per_tx = max_tx
    }
    if max_win.as_wei() > 0 {
        pol.max_per_window = max_win
    }
    pol
}

policy/src/decode.fe.content:
use ingot::types::{Address, Calldata, MAX_CALLDATA, SEL_APPROVE, SEL_TRANSFER, SEL_TRANSFER_FROM}

pub enum Erc20Call {
    Transfer(Address, u256),
    Approve(Address, u256),
    TransferFrom(Address, Address, u256),
    Malformed,
    Unknown,
}

impl Copy for Erc20Call {}
impl Snapshot for Erc20Call {}

pub fn selector_of(_ data: ref Calldata) -> Option<u32> {
    if data.len < 4 {
        Option::None
    } else {
        let b0 = (data.bytes[0] as u32) << 24
        let b1 = (data.bytes[1] as u32) << 16
        let b2 = (data.bytes[2] as u32) << 8
        let b3 = data.bytes[3] as u32
        Option::Some(b0 | b1 | b2 | b3)
    }
}

pub fn is_address_word(_ data: ref Calldata, offset: usize) -> bool {
    var i: usize = 0
    while i < 12 {
        if data.bytes[offset + i] != 0 {
            return false
        }
        i += 1
    }
    true
}

pub fn read_word(_ data: ref Calldata, offset: usize) -> u256 {
    var res: u256 = 0
    var i: usize = 0
    while i < 32 {
        res = (res << 8) | (data.bytes[offset + i] as u256)
        i += 1
    }
    res
}

pub fn read_address(_ data: ref Calldata, offset: usize) -> Address {
    let w = read_word(data, offset)
    Address::from_word_truncate(w)
}

pub fn decode_erc20(_ data: ref Calldata) -> Erc20Call {
    if data.len < 4 {
        return Erc20Call::Malformed
    }

    let sel = match selector_of(data) {
        Option::Some(s) => s,
        Option::None => {
            return Erc20Call::Malformed
        },
    }

    if sel == SEL_TRANSFER {
        if data.len != 68 {
            return Erc20Call::Malformed
        }
        if !is_address_word(data, offset: 4) {
            return Erc20Call::Malformed
        }
        let to = read_address(data, offset: 4)
        let amt = read_word(data, offset: 36)
        Erc20Call::Transfer(to, amt)
    } else if sel == SEL_APPROVE {
        if data.len != 68 {
            return Erc20Call::Malformed
        }
        if !is_address_word(data, offset: 4) {
            return Erc20Call::Malformed
        }
        let spender = read_address(data, offset: 4)
        let amt = read_word(data, offset: 36)
        Erc20Call::Approve(spender, amt)
    } else if sel == SEL_TRANSFER_FROM {
        if data.len != 100 {
            return Erc20Call::Malformed
        }
        if !is_address_word(data, offset: 4) {
            return Erc20Call::Malformed
        }
        if !is_address_word(data, offset: 36) {
            return Erc20Call::Malformed
        }
        let from = read_address(data, offset: 4)
        let to = read_address(data, offset: 36)
        let amt = read_word(data, offset: 68)
        Erc20Call::TransferFrom(from, to, amt)
    } else {
        Erc20Call::Unknown
    }
}

pub fn calldata_from_bytes(_ b: ref core::Bytes) -> Calldata {
    let span = b.span()
    let len = span.len()
    var bytes: [u8; MAX_CALLDATA] = [0; MAX_CALLDATA]
    let copy_len = if len > MAX_CALLDATA {
        MAX_CALLDATA
    } else {
        len
    }
    var i: usize = 0
    while i < copy_len {
        bytes[i] = span.byte_at(i)
        i = i + 1
    }
    Calldata { len, bytes }
}

policy/src/encoding.fe.content:
use ingot::types::{
    AgentState,
    BUCKETS,
    Bucket,
    MAX_RECIPIENTS,
    MAX_SELECTORS,
    MAX_TARGETS,
    MAX_TOKENS,
    Policy,
    TargetKind,
    TargetRule,
    Timestamp,
    TokenAmount,
    TokenRule,
    Window24,
}

pub const POLICY_WORDS: usize = 138
pub const STATE_WORDS: usize = 52

fn kind_to_u256(_ kind: TargetKind) -> u256 {
    match kind {
        TargetKind::Generic => 0,
        TargetKind::Erc20 => 1,
        TargetKind::UniswapRouter => 2,
        TargetKind::AavePool => 3,
    }
}

pub fn encode_policy(_ policy: Policy) -> [u256; POLICY_WORDS] {
    var words: [u256; POLICY_WORDS] = [0; POLICY_WORDS]
    var idx: usize = 0

    // 1. Version
    words[idx] = policy.version as u256
    idx += 1

    // 2. Targets
    words[idx] = policy.n_targets as u256
    idx += 1

    var t: usize = 0
    while t < MAX_TARGETS {
        let tgt = policy.targets[t]
        words[idx] = tgt.target.word()
        idx += 1
        words[idx] = kind_to_u256(tgt.kind)
        idx += 1
        words[idx] = if tgt.allow_eth_transfer { 1 } else { 0 }
        idx += 1
        words[idx] = if tgt.delegate_ok { 1 } else { 0 }
        idx += 1
        words[idx] = tgt.n_selectors as u256
        idx += 1

        var s: usize = 0
        while s < MAX_SELECTORS {
            words[idx] = tgt.selectors[s] as u256
            idx += 1
            s += 1
        }
        t += 1
    }

    // 3. ETH Caps
    words[idx] = policy.max_per_tx.as_wei()
    idx += 1
    words[idx] = policy.max_per_window.as_wei()
    idx += 1
    words[idx] = policy.window.as_seconds()
    idx += 1

    // 4. Tokens
    words[idx] = policy.n_tokens as u256
    idx += 1

    var tok: usize = 0
    while tok < MAX_TOKENS {
        let tk = policy.tokens[tok]
        words[idx] = tk.token.word()
        idx += 1
        words[idx] = tk.max_per_tx.as_u256()
        idx += 1
        words[idx] = tk.max_per_window.as_u256()
        idx += 1
        words[idx] = tk.max_approve.as_u256()
        idx += 1
        tok += 1
    }

    // 5. Phase 4 fields
    words[idx] = policy.n_recipients as u256
    idx += 1

    var r: usize = 0
    while r < MAX_RECIPIENTS {
        words[idx] = policy.recipients[r].word()
        idx += 1
        r += 1
    }

    words[idx] = policy.max_actions_per_window as u256
    idx += 1
    words[idx] = policy.cooldown.as_seconds()
    idx += 1
    words[idx] = policy.breaker_threshold as u256
    idx += 1

    words
}

pub fn encode_state(_ state: AgentState) -> [u256; STATE_WORDS] {
    var words: [u256; STATE_WORDS] = [0; STATE_WORDS]
    var idx: usize = 0

    words[idx] = if state.paused { 1 } else { 0 }
    idx += 1
    words[idx] = if state.tripped { 1 } else { 0 }
    idx += 1
    words[idx] = state.expiry.as_seconds()
    idx += 1

    // eth_window
    var b: usize = 0
    while b < BUCKETS {
        words[idx] = state.eth_window.buckets[b].index as u256
        idx += 1
        words[idx] = state.eth_window.buckets[b].amount
        idx += 1
        b += 1
    }

    words[idx] = state.last_action.as_seconds()
    idx += 1

    words
}

pub fn decode_state(_ words: [u256; STATE_WORDS]) -> AgentState {
    var idx: usize = 0
    let paused = words[idx] != 0
    idx += 1
    let tripped = words[idx] != 0
    idx += 1
    let expiry = Timestamp::from_seconds(words[idx])
    idx += 1

    // eth_window
    var eth_win = Window24::empty()
    var b: usize = 0
    while b < BUCKETS {
        eth_win.buckets[b] = Bucket {
            index: words[idx].downcast_truncate(),
            amount: words[idx + 1],
        }
        idx += 2
        b += 1
    }

    let last_action = Timestamp::from_seconds(words[idx])
    idx += 1

    AgentState {
        paused,
        tripped,
        expiry,
        eth_window: eth_win,
        last_action,
        action_window: Window24::empty(),
    }
}

pub fn decode_state_bytes(_ b: ref core::Bytes) -> Option<AgentState> {
    if b.len() != STATE_WORDS * 32 {
        return Option::None
    }
    var words: [u256; STATE_WORDS] = [0; STATE_WORDS]
    var w: usize = 0
    let span = b.span()
    while w < STATE_WORDS {
        var val: u256 = 0
        var byte_idx: usize = 0
        let base = w * 32
        while byte_idx < 32 {
            val = (val << 8) | (span.byte_at(base + byte_idx) as u256)
            byte_idx += 1
        }
        words[w] = val
        w += 1
    }
    Option::Some(decode_state(words))
}

