#[cfg(target = "evm")]
#[test]
fn test_mock_safe_basic() uses (evm: mut Evm) {
    let safe = evm.create<MockSafe>(value: Wei::zero(), args: ())
    let module_addr = evm.address()

    // Initially not enabled
    let is_en: bool = evm
        .call(
            addr: safe,
            gas: 100000,
            value: Wei::zero(),
            message: SafeMsg::IsModuleEnabled { module_addr },
        )
    assert(!is_en)

    // Enable module
    evm.call(
        addr: safe,
        gas: 100000,
        value: Wei::zero(),
        message: SafeMsg::EnableModule { module_addr },
    )
    let is_en2: bool = evm
        .call(
            addr: safe,
            gas: 100000,
            value: Wei::zero(),
            message: SafeMsg::IsModuleEnabled { module_addr },
        )
    assert(is_en2)

    // Execute tx
    let success: bool = evm
        .call(
            addr: safe,
            gas: 1000000,
            value: Wei::zero(),
            message: SafeMsg::ExecTransactionFromModule {
                to: Address::new(0x1234),
                value: 42,
                data: Bytes::empty(),
                operation: 0,
            },
        )
    assert(success)

    let count: u256 = evm
        .call(
            addr: safe,
            gas: 100000,
            value: Wei::zero(),
            message: SafeMsg::CallCount {},
        )
    assert(count == 1)

    let last_to: Address = evm
        .call(
            addr: safe,
            gas: 100000,
            value: Wei::zero(),
            message: SafeMsg::LastTo {},
        )
    assert(last_to == Address::new(0x1234))

    let last_val: u256 = evm
        .call(
            addr: safe,
            gas: 100000,
            value: Wei::zero(),
            message: SafeMsg::LastValue {},
        )
    assert(last_val == 42)

    // Test set_fail
    evm.call(
        addr: safe,
        gas: 100000,
        value: Wei::zero(),
        message: SafeMsg::SetFail { fail: true },
    )
    let success_fail: bool = evm
        .call(
            addr: safe,
            gas: 1000000,
            value: Wei::zero(),
            message: SafeMsg::ExecTransactionFromModule {
                to: Address::new(0x1234),
                value: 42,
                data: Bytes::empty(),
                operation: 0,
            },
        )
    assert(!success_fail)
}

